const e=[{id:"q_1",textFa:"ای برادر تو همه اندیشه‌ای، مابقی خود استخوان و ریشه‌ای. گر گلست اندیشهٔ تو گلشنی، ور بود خاری تو هیمهٔ گلخنی.",textEn:"You are entirely what you think; the rest is mere bone and fiber. If your thoughts are roses, you are a rose garden; if thorns, you are fuel for the furnace.",authorFa:"مولانا جلال‌الدین بلخی",authorEn:"Jalal al-Din Rumi",categoryFa:"خرد کهن و خودآگاهی",categoryEn:"Ancient Wisdom & Mind",theme:"wisdom"},{id:"q_2",textFa:"تن آدمی شریف است به جان آدمیت، نه همین لباس زیباست نشان آدمیت.",textEn:"Human dignity resides in the noble spirit within, not in the garments that adorn the outward form.",authorFa:"سعدی شیرازی",authorEn:"Saadi Shirazi",categoryFa:"اصالت و درستی",categoryEn:"Integrity & Character",theme:"integrity"},{id:"q_3",textFa:"درخت دوستی بنشان که کام دل به بار آرد، نهال دشمنی برکن که رنج بی‌شمار آرد.",textEn:"Plant the tree of friendship that brings joyful fruit; uproot the seedling of enmity that breeds endless sorrow.",authorFa:"حافظ شیرازی",authorEn:"Hafez of Shiraz",categoryFa:"عشق و پیوند انسانی",categoryEn:"Compassion & Friendship",theme:"wisdom"},{id:"q_4",textFa:"توانا بود هر که دانا بود، ز دانش دل پیر برنا بود.",textEn:"Capable is the one endowed with wisdom; through knowledge, even an aging heart is made young.",authorFa:"فردوسی طوسی",authorEn:"Ferdowsi",categoryFa:"دانش و خرد",categoryEn:"Knowledge & Power",theme:"learning"},{id:"q_5",textFa:"چون چرخ به کام یک خردمند نگشت، تو خواه فلک هفت شمر و خواهی هشت. چون باید مرد و آرزوها همه هشت، چه مور خورد به گور و چه گرگ به دشت.",textEn:"Since destiny never bows completely to the desires of the wise, live fully in the present; for earthly attachments are fleeting.",authorFa:"عمر خیام نیشابوری",authorEn:"Omar Khayyam",categoryFa:"آرامش در لحظه حال",categoryEn:"Mindfulness & Presence",theme:"mindfulness"},{id:"q_6",textFa:"نشان خردمندی آن است که آنچه را می‌داند بگوید، و آنچه را نمی‌داند به ندانستن آن اعتراف کند.",textEn:"The hallmark of true wisdom is to speak of what one knows, and to humbly admit what one does not.",authorFa:"ابوعلی سینا (پورسینا)",authorEn:"Avicenna (Ibn Sina)",categoryFa:"خرد و تواضع",categoryEn:"Humility & Truth",theme:"learning"},{id:"q_7",textFa:"گفتار نیک، پندار نیک، کردار نیک؛ سه چراغ راهنمایی که ظلمت نادانی را روشن می‌کنند.",textEn:"Good Thoughts, Good Words, Good Deeds; three eternal lanterns that dispel the darkness of ignorance.",authorFa:"زرتشت و خرد باستان",authorEn:"Ancient Persian Heritage",categoryFa:"اصول زندگی و درستی",categoryEn:"Core Principles",theme:"integrity"},{id:"q_8",textFa:"فرمان دادم تا بدنم را بدون تابوت و مومیایی به خاک بسپارند تا تک‌تک ذرات وجودم خاک ایران را بارور سازد.",textEn:"I commanded that my body be buried without coffin or gold, so that every part of me may enrich the soil of the earth.",authorFa:"کوروش بزرگ",authorEn:"Cyrus the Great",categoryFa:"بزرگی و تواضع",categoryEn:"Leadership & Humility",theme:"wisdom"},{id:"q_9",textFa:"درخت تو گر بار دانش بگیرد، به زیر آوری چرخ نیلوفری را.",textEn:"If your inner tree bears the fruit of knowledge, you shall bring the celestial heavens into your grasp.",authorFa:"ناصرخسرو قبادیانی",authorEn:"Naser Khosrow",categoryFa:"دانش و بینش",categoryEn:"Knowledge & Elevation",theme:"learning"},{id:"q_10",textFa:"هفت شهر عشق را عطار گشت، ما هنوز اندر خم یک کوچه‌ایم.",textEn:"Attar traversed the seven cities of transcendental love, while we remain wandering in the first bend of the alley.",authorFa:"عطار نیشابوری",authorEn:"Attar of Nishapur",categoryFa:"خودشناسی و تکامل",categoryEn:"Self-Realization",theme:"wisdom"},{id:"q_11",textFa:"نور حقیقت در درون هر انسان تابنده است؛ پرده‌های پندار را کنار بزن تا به اشراق برسی.",textEn:"The light of truth shines within every soul; unveil the shadows of illusion to attain illumination.",authorFa:"شیخ شهاب‌الدین سهروردی",authorEn:"Suhrawardi",categoryFa:"فلسفه اشراق",categoryEn:"Philosophy of Illumination",theme:"wisdom"},{id:"q_12",textFa:"همت بلند دار که مردان روزگار، از همت بلند به جایی رسیده‌اند.",textEn:"Cultivate lofty aspiration and unyielding will; for greatness has always been built on high ambition and perseverance.",authorFa:"نظامی گنجوی",authorEn:"Nizami Ganjavi",categoryFa:"همت و اراده",categoryEn:"Ambition & Willpower",theme:"wealth"},{id:"q_13",textFa:"تو بر ذهن خود کنترل داری، نه بر وقایع بیرونی. این حقیقت را دریاب تا به قدرتی بی‌پایان دست یابی.",textEn:"You have power over your mind, not outside events. Realize this, and you will find immense strength.",authorFa:"مارکوس اورلیوس",authorEn:"Marcus Aurelius",categoryFa:"رواقی‌گری و تسلط بر خود",categoryEn:"Stoicism & Self-Mastery",theme:"mindfulness"},{id:"q_14",textFa:"ما در تخیل و توهمات خود بیشتر رنج می‌بریم تا در واقعیت.",textEn:"We suffer more often in imagination than in reality.",authorFa:"لوکیوس سنکا",authorEn:"Seneca",categoryFa:"رهایی از اضطراب",categoryEn:"Anxiety Release",theme:"mindfulness"},{id:"q_15",textFa:"این رخدادها نیستند که انسان‌ها را آشفته می‌کنند، بلکه قضاوت و تفسیری است که درباره رخدادها دارند.",textEn:"Men are disturbed not by things, but by the view which they take of them.",authorFa:"اپیکتتوس",authorEn:"Epictetus",categoryFa:"وسعت دید و عدم قضاوت",categoryEn:"Perspective & Non-Judgment",theme:"wisdom"},{id:"q_16",textFa:"زندگی نیازموده، ارزش زیستن ندارد.",textEn:"The unexamined life is not worth living.",authorFa:"سقراط",authorEn:"Socrates",categoryFa:"خودشناسی و بازتاب",categoryEn:"Self-Inquiry",theme:"learning"},{id:"q_17",textFa:"تنها یک نیکی وجود دارد و آن دانش است، و تنها یک بدی وجود دارد و آن نادانی است.",textEn:"There is only one good, knowledge, and one evil, ignorance.",authorFa:"سقراط",authorEn:"Socrates",categoryFa:"دانایی و حقیقت",categoryEn:"Wisdom vs Ignorance",theme:"learning"},{id:"q_18",textFa:"پیروزی بر خویشتن، بزرگ‌ترین و باشکوه‌ترین پیروزی‌هاست.",textEn:"The first and greatest victory is to conquer yourself.",authorFa:"افلاطون",authorEn:"Plato",categoryFa:"تسلط بر نفس",categoryEn:"Self-Conquest",theme:"integrity"},{id:"q_19",textFa:"ما همان چیزی هستیم که مدام انجام می‌دهیم. پس تعالی یک عمل منفرد نیست، بلکه یک عادت است.",textEn:"We are what we repeatedly do. Excellence, then, is not an act, but a habit.",authorFa:"ارسطو",authorEn:"Aristotle",categoryFa:"عادت‌ها و انضباط",categoryEn:"Habits & Excellence",theme:"integrity"},{id:"q_20",textFa:"شناخت خود، سرآغاز تمام حکمت‌ها و بینش‌هاست.",textEn:"Knowing yourself is the beginning of all wisdom.",authorFa:"ارسطو",authorEn:"Aristotle",categoryFa:"خودشناسی عمیق",categoryEn:"Self-Knowledge",theme:"wisdom"},{id:"q_21",textFa:"هیچ بادی به نفع کشتی‌ای که نمی‌داند به کدام بندر می‌رود، نخواهد وزید.",textEn:"If a man knows not to which port he sails, no wind is favorable.",authorFa:"سنکا",authorEn:"Seneca",categoryFa:"هدفمندی و جهت‌گیری",categoryEn:"Purpose & Focus",theme:"wealth"},{id:"q_22",textFa:"بزرگ‌ترین ثروت، قناعت به داشته‌ها و داشتن ذهن بی‌نیاز و آرام است.",textEn:"To be content with little is true wealth; for nature is content with little.",authorFa:"اپیکور",authorEn:"Epicurus",categoryFa:"آرامش و قناعت",categoryEn:"Peace & Wealth",theme:"wealth"},{id:"q_23",textFa:"تا زمانی که ناخودآگاه را خودآگاه نکنید، زندگی شما را هدایت خواهد کرد و شما آن را تقدیر خواهید نامید.",textEn:"Until you make the unconscious conscious, it will direct your life and you will call it fate.",authorFa:"کارل گوستاو یونگ",authorEn:"Carl Gustav Jung",categoryFa:"روانشناسی عمیق",categoryEn:"Analytical Psychology",theme:"wisdom"},{id:"q_24",textFa:"کسی که به بیرون نگاه می‌کند خواب می‌بیند؛ کسی که به درون می‌نگرد بیدار می‌شود.",textEn:"Who looks outside, dreams; who looks inside, awakes.",authorFa:"کارل گوستاو یونگ",authorEn:"Carl Gustav Jung",categoryFa:"بیداری درونی",categoryEn:"Inner Awakening",theme:"wisdom"},{id:"q_25",textFa:"کسی که چرایی برای زیستن دارد، می‌تواند با هر چگونگی بسازد و از هر طوفانی بگذرد.",textEn:"He who has a why to live for can bear almost any how.",authorFa:"ویکتور فرانکل (انسان در جستجوی معنا)",authorEn:"Viktor Frankl",categoryFa:"معنای زندگی و تاب‌آوری",categoryEn:"Meaning & Resilience",theme:"wisdom"},{id:"q_26",textFa:"در میان محرک و پاسخ، فضایی وجود دارد. در آن فضا، آزادی و قدرت ما برای انتخاب پاسخمان نهفته است.",textEn:"Between stimulus and response there is a space. In that space is our power to choose our response.",authorFa:"ویکتور فرانکل",authorEn:"Viktor Frankl",categoryFa:"آزادی انتخاب و آرامش",categoryEn:"Freedom of Choice",theme:"mindfulness"},{id:"q_27",textFa:"بزرگ‌ترین کشف نسل من این است که انسان می‌تواند با تغییر دادن نگرش ذهنی خود، زندگی‌اش را متحول سازد.",textEn:"The greatest discovery of my generation is that human beings can alter their lives by altering their attitudes of mind.",authorFa:"ویلیام جیمز",authorEn:"William James",categoryFa:"قدرت ذهن",categoryEn:"Mental Mastery",theme:"learning"},{id:"q_28",textFa:"پذیرش واقعیت، نخستین گام در درمان هر گونه رنج روانی است.",textEn:"The curious paradox is that when I accept myself just as I am, then I can change.",authorFa:"کارل راجرز",authorEn:"Carl Rogers",categoryFa:"پذیرش و رشد فردی",categoryEn:"Radical Acceptance",theme:"mindfulness"},{id:"q_29",textFa:"تنها چیزی که باید از آن بترسیم، خود ترس فلج‌کننده و بی‌اساس است.",textEn:"The only thing we have to fear is fear itself.",authorFa:"فرانکلین روزولت",authorEn:"Franklin D. Roosevelt",categoryFa:"شجاعت و غلبه بر ترس",categoryEn:"Courage & Breakthrough",theme:"wisdom"},{id:"q_30",textFa:"سکوت، پاسخ خردمندان به هیاهوی جهان است.",textEn:"Silence is a source of great strength; in quiet contemplation we find our true power.",authorFa:"لائوتسه",authorEn:"Lao Tzu",categoryFa:"سکوت ذهن و آرامش",categoryEn:"Mindfulness & Silence",theme:"mindfulness"},{id:"q_31",textFa:"تخیل مهم‌تر از دانش است؛ زیرا دانش محدود به آنچه می‌دانیم است، اما تخیل تمام کیهان را در بر می‌گیرد.",textEn:"Imagination is more important than knowledge. For knowledge is limited, whereas imagination embraces the entire world.",authorFa:"آلبرت انیشتین",authorEn:"Albert Einstein",categoryFa:"علم و خلاقیت",categoryEn:"Science & Imagination",theme:"learning"},{id:"q_32",textFa:"زندگی مانند دوچرخه‌سواری است؛ برای حفظ تعادل، باید همیشه در حال حرکت باشید.",textEn:"Life is like riding a bicycle. To keep your balance, you must keep moving.",authorFa:"آلبرت انیشتین",authorEn:"Albert Einstein",categoryFa:"حرکت و تعادل",categoryEn:"Balance & Momentum",theme:"mindfulness"},{id:"q_33",textFa:"ما غبار ستارگانیم که به خودآگاهی رسیده‌ایم تا کیهان را کشف و درک کنیم.",textEn:"We are a way for the cosmos to know itself; some part of our being knows this is where we came from.",authorFa:"کارل سیگن",authorEn:"Carl Sagan",categoryFa:"کیهان و آگاهی",categoryEn:"Cosmic Perspective",theme:"wisdom"},{id:"q_34",textFa:"نگاهت را به ستارگان بدوز، نه به پاهایت. کنجکاو باش و تلاش کن جهان پیرامونت را بفهمی.",textEn:"Look up at the stars and not down at your feet. Try to make sense of what you see, and wonder about what makes the universe exist.",authorFa:"استیون هاوکینگ",authorEn:"Stephen Hawking",categoryFa:"کنجکاوی و وسعت نظر",categoryEn:"Curiosity & Wonder",theme:"learning"},{id:"q_35",textFa:"اصل اول این است که خودت را فریب ندهی، و تو ساده‌ترین فرد برای فریب دادن هستی.",textEn:"The first principle is that you must not fool yourself and you are the easiest person to fool.",authorFa:"ریچارد فاینمن",authorEn:"Richard Feynman",categoryFa:"صداقت علمی و تفکر نقاد",categoryEn:"Critical Thinking & Truth",theme:"integrity"},{id:"q_36",textFa:"هیچ چیزی در زندگی برای ترسیدن وجود ندارد، فقط باید آن را فهمید و درک کرد.",textEn:"Nothing in life is to be feared, it is only to be understood. Now is the time to understand more, so that we may fear less.",authorFa:"ماری کوری",authorEn:"Marie Curie",categoryFa:"دانش و رهایی از هراس",categoryEn:"Courage & Understanding",theme:"learning"},{id:"q_37",textFa:"اگر می‌خواهی اسرار جهان را بیابی، به انرژی، فرکانس و ارتعاش فکر کن.",textEn:"If you want to find the secrets of the universe, think in terms of energy, frequency and vibration.",authorFa:"نیکولا تسلا",authorEn:"Nikola Tesla",categoryFa:"انرژی و کیهان",categoryEn:"Energy & Frequency",theme:"learning"},{id:"q_38",textFa:"طبیعت به زبان ریاضیات نگاشته شده است.",textEn:"The book of nature is written in the language of mathematics.",authorFa:"گالیلئو گالیله",authorEn:"Galileo Galilei",categoryFa:"علم و طبیعت",categoryEn:"Laws of Nature",theme:"learning"},{id:"q_39",textFa:"آنچه مرا نکشد، قوی‌ترم می‌سازد.",textEn:"What does not kill me makes me stronger.",authorFa:"فریدریش نیچه",authorEn:"Friedrich Nietzsche",categoryFa:"اراده و تاب‌آوری",categoryEn:"Resilience & Willpower",theme:"integrity"},{id:"q_40",textFa:"تو باید آشوبی در درون داشته باشی تا بتوانی ستاره‌ای رقصان بیافرینی.",textEn:"You must have chaos within you to give birth to a dancing star.",authorFa:"فریدریش نیچه",authorEn:"Friedrich Nietzsche",categoryFa:"خلاقیت و دگرگونی",categoryEn:"Creativity & Transformation",theme:"wisdom"},{id:"q_41",textFa:"بزرگ‌ترین حکمت آن است که ارزش داشته‌های کنونی‌ات را بدانی، پیش از آنکه زمان آن‌ها را از تو بگیرد.",textEn:"Most men pursue pleasure with such breathless haste that they hurry past it.",authorFa:"سورن کی‌یرکگور",authorEn:"Soren Kierkegaard",categoryFa:"حضور در لحظه",categoryEn:"Present Awareness",theme:"mindfulness"},{id:"q_42",textFa:"انسان محکوم به آزادی است؛ زیرا به محض اینکه به این جهان پا گذاشت، مسئول تمام کارهای خویش است.",textEn:"Man is condemned to be free; because once thrown into the world, he is responsible for everything he does.",authorFa:"ژان پل سارتر",authorEn:"Jean-Paul Sartre",categoryFa:"مسئولیت‌پذیری شخصی",categoryEn:"Radical Responsibility",theme:"integrity"},{id:"q_43",textFa:"در میانه زمستان، سرانجام دریافتم که در درون من، تابستانی شکست‌ناپذیر شکوفاست.",textEn:"In the midst of winter, I found there was, within me, an invincible summer.",authorFa:"آلبر کامو",authorEn:"Albert Camus",categoryFa:"امید و قدرت درون",categoryEn:"Invincible Hope",theme:"wisdom"},{id:"q_44",textFa:"ثروت حقیقی مانند آب دریاست؛ هرچه بیشتر از آن بنوشی، تشنه‌تر می‌شوی، مگر آنکه معنا و روحی در آن جاری باشد.",textEn:"Wealth is like sea-water; the more we drink, the thirstier we become; and the same is true of fame.",authorFa:"آرتور شوپنهاور",authorEn:"Arthur Schopenhauer",categoryFa:"فلسفه ثروت و معنا",categoryEn:"Wealth & Wisdom",theme:"wealth"},{id:"q_45",textFa:"دو چیز روح مرا از احترامی روزافزون پر می‌کند: آسمان پرستاره بالای سرم و قانون اخلاقی درون وجودم.",textEn:"Two things fill the mind with ever-increasing wonder and awe: the starry heavens above me and the moral law within me.",authorFa:"امانوئل کانت",authorEn:"Immanuel Kant",categoryFa:"وجدان و شکوه کیهان",categoryEn:"Morality & Wonder",theme:"integrity"},{id:"q_46",textFa:"آرامش ذهن، بالاترین خیر و نیکی در وجود انسان است.",textEn:"Peace is not the absence of war, but a virtue based on strength of character.",authorFa:"باروخ اسپینوزا",authorEn:"Baruch Spinoza",categoryFa:"آرامش روح و فلسفه",categoryEn:"Inner Peace",theme:"mindfulness"},{id:"q_47",textFa:"موفقیت مجموعه‌ای از تلاش‌های کوچک و متوالی است که هر روز، بدون وقفه تکرار می‌شوند.",textEn:"Success is the sum of small efforts, repeated day in and day out.",authorFa:"رابرت کولیر",authorEn:"Robert Collier",categoryFa:"استمرار و عادت‌ها",categoryEn:"Consistency & Small Steps",theme:"wealth"},{id:"q_48",textFa:"انضباط شخصی پلی است میان اهداف درخشان و دستاوردهای واقعی.",textEn:"Discipline is the bridge between goals and accomplishment.",authorFa:"جیم ران",authorEn:"Jim Rohn",categoryFa:"انضباط شخصی",categoryEn:"Discipline & Bridges",theme:"integrity"},{id:"q_49",textFa:"زمان شما محدود است، پس آن را با زندگی کردن بر اساس خواسته دیگران هدر ندهید.",textEn:"Your time is limited, so don’t waste it living someone else’s life.",authorFa:"استیو جابز",authorEn:"Steve Jobs",categoryFa:"اصالت و جسارت",categoryEn:"Authenticity & Focus",theme:"wealth"},{id:"q_50",textFa:"گرسنه‌بمان، احمق‌بمان؛ همیشه به دنبال یادگیری عمیق و ناشناخته‌ها باش.",textEn:"Stay hungry, stay foolish.",authorFa:"استیو جابز",authorEn:"Steve Jobs",categoryFa:"اشتیاق یادگیری",categoryEn:"Continuous Learning",theme:"learning"},{id:"q_51",textFa:"بهترین سرمایه‌گذاری که می‌توانید انجام دهید، سرمایه‌گذاری روی رشد و مهارت‌های خودتان است.",textEn:"The best investment you can make is an investment in yourself.",authorFa:"وارن بافت",authorEn:"Warren Buffett",categoryFa:"سرمایه‌گذاری روی خود",categoryEn:"Self-Investment",theme:"wealth"},{id:"q_52",textFa:"قانون اول ثروت: پول خود را از دست ندهید. قانون دوم: قانون اول را هرگز فراموش نکنید.",textEn:"Rule No. 1: Never lose money. Rule No. 2: Never forget rule No. 1.",authorFa:"وارن بافت",authorEn:"Warren Buffett",categoryFa:"هوش مالی و امنیت",categoryEn:"Financial Security",theme:"wealth"},{id:"q_53",textFa:"در میانه هر دشواری و بحران، فرصتی طلایی نهفته است.",textEn:"In the middle of difficulty lies opportunity.",authorFa:"آلبرت انیشتین",authorEn:"Albert Einstein",categoryFa:"دیدگاه مثبت و فرصت‌طلبی",categoryEn:"Opportunity in Crisis",theme:"wealth"},{id:"q_54",textFa:"استراتژی برتر آن است که برنده شوی بدون آنکه نیاز به جنگیدن ویرانگر باشد.",textEn:"The supreme art of war is to subdue the enemy without fighting.",authorFa:"سون تزو (هنر جنگ)",authorEn:"Sun Tzu",categoryFa:"استراتژی و هوشمندی",categoryEn:"Strategy & Mastery",theme:"wealth"},{id:"q_55",textFa:"اگر می‌خواهی کاری بزرگ انجام دهی، اول باید به کوچک‌ترین کارهایت بیشترین اهمیت را بدهی.",textEn:"If you want to do great things, you must first pay immense attention to the smallest details.",authorFa:"کنفوسیوس",authorEn:"Confucius",categoryFa:"دقت و انضباط",categoryEn:"Mastery in Details",theme:"integrity"},{id:"q_56",textFa:"موفقیت، رفتن از شکستی به شکست دیگر است، بدون آنکه اشتیاق و انگیزه خود را از دست بدهید.",textEn:"Success is stumbling from failure to failure with no loss of enthusiasm.",authorFa:"وینستون چرچیل",authorEn:"Winston Churchill",categoryFa:"پشتکار و مقاومت",categoryEn:"Grit & Perseverance",theme:"wealth"},{id:"q_57",textFa:"سادگی، نهایت کمال و پیچیدگی است.",textEn:"Simplicity is the ultimate sophistication.",authorFa:"لئوناردو داوینچی",authorEn:"Leonardo da Vinci",categoryFa:"سادگی و خرد هنری",categoryEn:"Simplicity & Genius",theme:"learning"},{id:"q_58",textFa:"من مجسمه را نمی‌سازم؛ پیکره باشکوه از قبل در دل سنگ مرمر وجود دارد، من فقط زواید را می‌تراشم.",textEn:"I saw the angel in the marble and carved until I set him free.",authorFa:"میکل‌آنژ",authorEn:"Michelangelo",categoryFa:"خلق شاهکار و پالایش",categoryEn:"Refinement & Vision",theme:"wisdom"},{id:"q_59",textFa:"اگر صدایی از درون به شما گفت «نمی‌توانی نقاشی کنی»، حتماً نقاشی کن تا آن صدا تا ابد خاموش شود.",textEn:"If you hear a voice within you say “you cannot paint,” then by all means paint, and that voice will be silenced.",authorFa:"ونسان ونگوگ",authorEn:"Vincent van Gogh",categoryFa:"غلبه بر تردید و هنر",categoryEn:"Silencing Self-Doubt",theme:"learning"},{id:"q_60",textFa:"همه انسان‌ها به فکر تغییر جهانند، اما هیچ‌کس به فکر تغییر دادن خود نیست.",textEn:"Everyone thinks of changing the world, but no one thinks of changing himself.",authorFa:"لئو تولستوی",authorEn:"Leo Tolstoy",categoryFa:"تغییر از درون",categoryEn:"Inner Transformation",theme:"wisdom"},{id:"q_61",textFa:"راز وجود بشر فقط در زنده ماندن نیست، بلکه در یافتن چیزی است که برای آن زندگی کند.",textEn:"The mystery of human existence lies not in just staying alive, but in finding something to live for.",authorFa:"فئودور داستایفسکی",authorEn:"Fyodor Dostoevsky",categoryFa:"معنا و هدفمندی",categoryEn:"Soul & Purpose",theme:"wisdom"},{id:"q_62",textFa:"زیبایی جهان را نجات خواهد داد.",textEn:"Beauty will save the world.",authorFa:"فئودور داستایفسکی",authorEn:"Fyodor Dostoevsky",categoryFa:"هنر و زیبایی‌شناسی",categoryEn:"Aesthetics & Healing",theme:"mindfulness"},{id:"q_63",textFa:"بودن یا نبودن؛ مسئله این است که آیا در برابر تازیانه‌های روزگار شکیبا باشیم یا سلاح برگیریم و سرنوشت را بسازیم.",textEn:"To be, or not to be, that is the question: whether ’tis nobler in the mind to suffer or to take arms against a sea of troubles.",authorFa:"ویلیام شکسپیر",authorEn:"William Shakespeare",categoryFa:"انتخاب و هستی",categoryEn:"Existential Courage",theme:"wisdom"},{id:"q_64",textFa:"چشمانت را باز کن تا زیبایی را در اشکال ساده جهان ببینی؛ معجزه‌ها در هر گوشه منتظر توجه تو هستند.",textEn:"Trust in dreams, for in them is hidden the gate to eternity.",authorFa:"جبران خلیل جبران",authorEn:"Kahlil Gibran",categoryFa:"بینش شاعرانه و خرد",categoryEn:"Poetic Wisdom",theme:"mindfulness"},{id:"q_65",textFa:"سفری به طول هزار فرسنگ، با برداشتن نخستین گام آغاز می‌شود.",textEn:"The journey of a thousand miles begins with a single step.",authorFa:"لائوتسه (دائو دِ جینگ)",authorEn:"Lao Tzu",categoryFa:"شروع قدرتمند و گام اول",categoryEn:"First Steps & Tao",theme:"learning"},{id:"q_66",textFa:"آب زلال‌ترین و منعطف‌ترین عنصر جهان است، اما بر سخت‌ترین سنگ‌ها چیره می‌شود. مانند آب نرم باش.",textEn:"Nothing is softer or more flexible than water, yet nothing can resist it. Be like water.",authorFa:"لائوتسه",authorEn:"Lao Tzu",categoryFa:"انعطاف‌پذیری و جریان",categoryEn:"Fluidity & Soft Power",theme:"mindfulness"},{id:"q_67",textFa:"ذهن خاموش، پناهگاهی امن در برابر طوفان‌های افکار سرگردان است.",textEn:"To the mind that is still, the whole universe surrenders.",authorFa:"چوانگ تسی",authorEn:"Zhuangzi",categoryFa:"سکون ذهن و مراقبه",categoryEn:"Stillness & Surrender",theme:"mindfulness"},{id:"q_68",textFa:"در گذشته غرق نشو، در رویای آینده گم نشو، ذهنت را بر لحظه اکنون متمرکز ساز.",textEn:"Do not dwell in the past, do not dream of the future, concentrate the mind on the present moment.",authorFa:"گوتاما بودا",authorEn:"Gautama Buddha",categoryFa:"حضور و تمرکز ذهن",categoryEn:"Presence & Focus",theme:"mindfulness"},{id:"q_69",textFa:"درد و رنج بدنی اجتناب‌ناپذیر است، اما رنج کشیدن روانی انتخابی است.",textEn:"Pain is inevitable. Suffering is optional.",authorFa:"هاروکی موراکامی / خرد ذن",authorEn:"Haruki Murakami / Zen Wisdom",categoryFa:"تاب‌آوری روانی",categoryEn:"Freedom from Suffering",theme:"mindfulness"},{id:"q_70",textFa:"اگر چیزی را برای مدت زیادی در دست بگیری خسته می‌شوی؛ راز آرامش در رها کردن است.",textEn:"Let go of what was, accept what is, and have faith in what will be.",authorFa:"خرد کهن شرق",authorEn:"Eastern Philosophy",categoryFa:"رهاسازی و آرامش",categoryEn:"Art of Letting Go",theme:"mindfulness"},{id:"q_71",textFa:"تغییری باش که می‌خواهی در جهان ببینی.",textEn:"Be the change that you wish to see in the world.",authorFa:"ماهاتما گاندی",authorEn:"Mahatma Gandhi",categoryFa:"الگوسازی و عمل",categoryEn:"Living the Example",theme:"integrity"},{id:"q_72",textFa:"شجاعت، نبود ترس نیست؛ بلکه پیروزی بر ترس و غلبه بر آن است.",textEn:"Courage is not the absence of fear, but the triumph over it.",authorFa:"نلسون ماندلا",authorEn:"Nelson Mandela",categoryFa:"شجاعت و استقامت",categoryEn:"Courage & Triumph",theme:"integrity"},{id:"q_73",textFa:"آموزش و آگاهی، قدرتمندترین سلاحی است که می‌توانید برای تغییر جهان به کار گیرید.",textEn:"Education is the most powerful weapon which you can use to change the world.",authorFa:"نلسون ماندلا",authorEn:"Nelson Mandela",categoryFa:"دانش و دگرگونی",categoryEn:"Power of Education",theme:"learning"},{id:"q_74",textFa:"تاریکی نمی‌تواند تاریکی را براند؛ تنها نور قادر به آن است. نفرت نمی‌تواند نفرت را محو کند؛ تنها عشق می‌تواند.",textEn:"Darkness cannot drive out darkness; only light can do that. Hate cannot drive out hate; only love can do that.",authorFa:"مارتین لوتر کینگ جونیور",authorEn:"Martin Luther King Jr.",categoryFa:"نور، عشق و دگرگونی",categoryEn:"Light & Compassion",theme:"integrity"},{id:"q_75",textFa:"ارزش واقعی یک انسان با آنچه به دیگران می‌بخشد سنجیده می‌شود، نه با آنچه به دست می‌آورد.",textEn:"The value of a man should be seen in what he gives and not in what he is able to receive.",authorFa:"آلبرت انیشتین",authorEn:"Albert Einstein",categoryFa:"بخشندگی و خدمت",categoryEn:"Generosity & Value",theme:"integrity"},{id:"q_76",textFa:"تمرکز، توانایی گفتن «نه» به صدها ایده خوب دیگر است تا بتوانی بهترین را به کمال برسانی.",textEn:"Focusing is about saying No. You’ve got to say no, no, no to a hundred other good ideas.",authorFa:"استیو جابز",authorEn:"Steve Jobs",categoryFa:"تمرکز و انضباط اولویت",categoryEn:"Deep Focus & Essentialism",theme:"wealth"},{id:"q_77",textFa:"کار عمیق در سکوت و تمرکز کامل، ارزشمندترین مهارت قرن بیست و یکم است.",textEn:"The ability to perform deep work is becoming increasingly rare and simultaneously increasingly valuable.",authorFa:"کال نیوپورت",authorEn:"Cal Newport",categoryFa:"کار عمیق و بهره‌وری",categoryEn:"Deep Work Mastery",theme:"learning"},{id:"q_78",textFa:"بهترین راه پیش‌بینی آینده، خلق کردن آن با دستان خودتان در لحظه حال است.",textEn:"The best way to predict the future is to create it.",authorFa:"پیتر دراکر",authorEn:"Peter Drucker",categoryFa:"آینده‌سازی و عاملیت",categoryEn:"Creating the Future",theme:"wealth"},{id:"q_79",textFa:"انگیزه چیزی است که شما را به شروع وا می‌دارد؛ عادت همان چیزی است که شما را به پیش می‌برد.",textEn:"Motivation is what gets you started. Habit is what keeps you going.",authorFa:"جیم ران",authorEn:"Jim Rohn",categoryFa:"عادت و استمرار",categoryEn:"Habit & Continuity",theme:"integrity"},{id:"q_80",textFa:"اگر هر روز ۱٪ بهتر شوید، در پایان سال ۳۷ برابر قدرتمندتر و ماهرتر خواهید بود.",textEn:"If you get 1% better each day for one year, you’ll end up thirty-seven times better.",authorFa:"جیمز کلیر (عادت‌های اتمی)",authorEn:"James Clear",categoryFa:"رشد تصاعدی و عادات اتمی",categoryEn:"Atomic Habits & Compounding",theme:"learning"},{id:"q_81",textFa:"آب زنید راه را هین که نگار می‌رسد، مژده دهید باغ را بوی بهار می‌رسد.",textEn:"Sprinkle the pathway with rosewater, for the Beloved arrives; bring joyful news to the garden, spring is near.",authorFa:"مولانا",authorEn:"Rumi",categoryFa:"شادی درون و امید",categoryEn:"Joy & Renewal",theme:"mindfulness"},{id:"q_82",textFa:"چو عضوی به درد آورد روزگار، دگر عضوها را نماند قرار.",textEn:"When one limb of humanity aches with pain, no other limb can remain at rest.",authorFa:"سعدی شیرازی",authorEn:"Saadi Shirazi",categoryFa:"همدلی و انسانیت",categoryEn:"Universal Empathy",theme:"integrity"},{id:"q_83",textFa:"غم مخور جانا درین عالم که هر نوری پس از شامی پدید آید.",textEn:"Grieve not, for in this world every radiant morning follows a dark night.",authorFa:"عطار نیشابوری",authorEn:"Attar",categoryFa:"امید و گذرا بودن رنج",categoryEn:"Hope & Transience",theme:"mindfulness"},{id:"q_84",textFa:"زندگی نه جستجوی خویشتن، بلکه ساختن و آفرینش آگاهانه خویشتن است.",textEn:"Life isn’t about finding yourself. Life is about creating yourself.",authorFa:"جورج برنارد شاو",authorEn:"George Bernard Shaw",categoryFa:"آفرینش خود",categoryEn:"Self-Creation",theme:"wisdom"},{id:"q_85",textFa:"راز خوشبختی در آزادی است، و راز آزادی در شجاعت نهفته است.",textEn:"The secret to happiness is freedom… And the secret to freedom is courage.",authorFa:"توسیدیدس",authorEn:"Thucydides",categoryFa:"آزادی و شجاعت",categoryEn:"Freedom & Courage",theme:"integrity"},{id:"q_86",textFa:"ذهن مانند چتر نجات است؛ تنها زمانی کار می‌کند که باز باشد.",textEn:"The mind is like a parachute. It doesn’t work if it’s not open.",authorFa:"فرانک زاپا",authorEn:"Frank Zappa",categoryFa:"گشودگی ذهن",categoryEn:"Open-Mindedness",theme:"learning"},{id:"q_87",textFa:"بزرگ‌ترین دشمن دانش، نادانی و جهل نیست؛ بلکه توهم دانستن است.",textEn:"The greatest enemy of knowledge is not ignorance, it is the illusion of knowledge.",authorFa:"استیون هاوکینگ",authorEn:"Stephen Hawking",categoryFa:"تواضع علمی",categoryEn:"Intellectual Humility",theme:"learning"},{id:"q_88",textFa:"هرگز اجازه ندهید آنچه نمی‌توانید انجام دهید، مانع انجام آنچه می‌توانید شود.",textEn:"Do not let what you cannot do interfere with what you can do.",authorFa:"جان وودن",authorEn:"John Wooden",categoryFa:"تمرکز بر دایره نفوذ",categoryEn:"Circle of Influence",theme:"integrity"},{id:"q_89",textFa:"تنها راه انجام کارهای واقعاً بزرگ، عشق ورزیدن به کاری است که انجام می‌دهید.",textEn:"The only way to do great work is to love what you do.",authorFa:"استیو جابز",authorEn:"Steve Jobs",categoryFa:"اشتیاق و هنر کار",categoryEn:"Passion & Craftsmanship",theme:"wealth"},{id:"q_90",textFa:"هر روز فرصتی تازه است برای تبدیل شدن به بهترین نسخه‌ای که می‌توانید باشید.",textEn:"Every single day is a fresh opportunity to sculpt the highest version of yourself.",authorFa:"خرد معاصر",authorEn:"Modern Wisdom",categoryFa:"آغاز نو و امید",categoryEn:"New Beginnings",theme:"mindfulness"},{id:"q_91",textFa:"صبر تلخ است، ولیکن برِ شیرین دارد.",textEn:"Patience is bitter, but its fruit is sweet.",authorFa:"سعدی شیرازی",authorEn:"Saadi",categoryFa:"صبر و پاداش استمرار",categoryEn:"Patience & Rewards",theme:"integrity"},{id:"q_92",textFa:"چو بشنوی سخن اهل دل، مگو که خطاست؛ سخن‌شناس نه‌ای جان من، خطا اینجاست.",textEn:"When you hear the wisdom of enlightened souls, do not call it error; humility is learning to listen deeply.",authorFa:"حافظ شیرازی",authorEn:"Hafez",categoryFa:"گوش سپردن و خرد",categoryEn:"Deep Listening",theme:"wisdom"},{id:"q_93",textFa:"از دی که گذشت هیچ ازو یاد مکن، فردا که نیامده‌ست فریاد مکن. بر نامده و گذشته بنیاد مکن، حالی خوش باش و عمر بر باد مکن.",textEn:"Waste not your soul mourning yesterday or fearing tomorrow; anchor your heart in the sacred beauty of now.",authorFa:"عمر خیام",authorEn:"Omar Khayyam",categoryFa:"حضور و رهایی از حسرت",categoryEn:"Mindfulness & Time",theme:"mindfulness"},{id:"q_94",textFa:"شجاعت این نیست که انرژی داشته باشی برای ادامه دادن؛ شجاعت این است که وقتی انرژی نداری ادامه دهی.",textEn:"Courage is not having the strength to go on; it is going on when you don’t have the strength.",authorFa:"تئودور روزولت",authorEn:"Theodore Roosevelt",categoryFa:"شجاعت و پایداری",categoryEn:"Grit in Adversity",theme:"integrity"},{id:"q_95",textFa:"دانش بدون عمل مانند درختی بی‌ثمر، و عمل بدون دانش مانند راه رفتن در تاریکی است.",textEn:"Knowledge without action is like a tree without fruit; action without knowledge is stumbling in the dark.",authorFa:"خرد کهن فارسی",authorEn:"Classic Persian Proverb",categoryFa:"عمل‌گرایی آگاهانه",categoryEn:"Actionable Knowledge",theme:"learning"},{id:"q_96",textFa:"ذهن انسان مانند یک باغ است؛ می‌تواند گلستان باشد یا علفزار هرز. بذر افکارت را آگاهانه انتخاب کن.",textEn:"A man’s mind may be likened to a garden, which may be intelligently cultivated or allowed to run wild.",authorFa:"جیمز الن",authorEn:"James Allen",categoryFa:"پرورش ذهن",categoryEn:"Mind Cultivation",theme:"mindfulness"},{id:"q_97",textFa:"شکست پایان راه نیست؛ شکست درس و قطب‌نمایی است برای مسیر بهتر.",textEn:"Failure is not the opposite of success; it’s part of success.",authorFa:"آریانا هافینگتون",authorEn:"Arianna Huffington",categoryFa:"دیدگاه نسبت به شکست",categoryEn:"Embracing Failure",theme:"wealth"},{id:"q_98",textFa:"سرمایه‌ای باارزش‌تر از زمان و توجه متمرکز وجود ندارد؛ آن را به بیهودگی نفروش.",textEn:"Your time and attention are the most precious currencies in existence; guard them with vigilance.",authorFa:"سنکا",authorEn:"Seneca",categoryFa:"مدیریت زمان و تمرکز",categoryEn:"Time Management",theme:"wealth"},{id:"q_99",textFa:"هرگاه که می‌خواهی به خشم پاسخ دهی، نفسی عمیق بکش؛ سکوت در آن لحظه قوی‌ترین زره توست.",textEn:"Whenever you are angry, be assured that it is an evil and that you have added to a habit. Take a deep breath.",authorFa:"اپیکتتوس",authorEn:"Epictetus",categoryFa:"مهار خشم و خونسردی",categoryEn:"Emotional Mastery",theme:"mindfulness"},{id:"q_100",textFa:"کمال‌گرایی افراطی، دشمن اصلی پیشرفت و حرکت است. شروع کن و در مسیر بهتر شو.",textEn:"Done is better than perfect. Start now and refine continuously.",authorFa:"خرد مدرن بهره‌وری",authorEn:"Modern Productivity",categoryFa:"اقدام و حرکت",categoryEn:"Action over Perfection",theme:"learning"},{id:"q_101",textFa:"خوشبختی چیزی نیست که از پیش ساخته شده باشد؛ بلکه از اعمال و تصمیمات روزانه شما پدید می‌آید.",textEn:"Happiness is not something ready made. It comes from your own actions.",authorFa:"دالایی لاما",authorEn:"Dalai Lama",categoryFa:"شادکامی و عاملیت",categoryEn:"Agency & Happiness",theme:"mindfulness"},{id:"q_102",textFa:"هیچ کوهی آن‌قدر بلند نیست که راهی برای صعود از آن وجود نداشته باشد.",textEn:"No mountain is so high that a determined spirit cannot summit its peak.",authorFa:"حکمت کهن",authorEn:"Ancient Proverb",categoryFa:"پشتکار و اراده",categoryEn:"Unyielding Spirit",theme:"wealth"},{id:"q_103",textFa:"اگر در صلح با خویشتن نباشی، در هیچ کجای جهان آرامش نخواهی یافت.",textEn:"If you are not at peace with yourself, you will find peace nowhere else in the world.",authorFa:"خرد اگزیستانسیال",authorEn:"Inner Peace Wisdom",categoryFa:"صلح درونی",categoryEn:"Inner Reconciliation",theme:"mindfulness"},{id:"q_104",textFa:"روشنایی در درون توست؛ شمع امید را در دلت همواره روشن نگه دار.",textEn:"The light is within you; keep the sacred candle of hope burning steadfastly.",authorFa:"مولانا",authorEn:"Rumi",categoryFa:"امید و روشنایی",categoryEn:"Inner Illumination",theme:"wisdom"},{id:"q_105",textFa:"تو فقط قطره‌ای در اقیانوس نیستی؛ تو تمام اقیانوسی در یک قطره.",textEn:"You are not a drop in the ocean; you are the entire ocean in a drop.",authorFa:"شمس تبریزی",authorEn:"Shams Tabrizi",categoryFa:"عرفان و وسعت وجود",categoryEn:"Mysticism & Infinite Being",theme:"wisdom"},{id:"q_106",textFa:"چشم‌ها را باید شست، جور دیگر باید دید. واژه‌ها را باید شست، واژه باید خود باد، واژه باید خود باران باشد.",textEn:"We must wash our eyes, we must see in a new way. Cleanse your perception to embrace pure wonder.",authorFa:"سهراب سپهری",authorEn:"Sohrab Sepehri",categoryFa:"نگاه نو و زلالی ذهن",categoryEn:"Fresh Perception",theme:"mindfulness"},{id:"q_107",textFa:"پرواز را به خاطر بسپار، پرنده مردنی است.",textEn:"Remember the flight; the bird is mortal.",authorFa:"فروغ فرخزاد",authorEn:"Forough Farrokhzad",categoryFa:"جاودانگی و معنا",categoryEn:"Legacy & Transcendence",theme:"wisdom"},{id:"q_108",textFa:"ذهن خود را خالی کن؛ بی‌شکل باش، مانند آب. وقتی آب را در فنجان می‌ریزی، فنجان می‌شود. مثل آب باش رفیق من.",textEn:"Empty your mind, be formless, shapeless, like water. Now you put water into a cup, it becomes the cup. Be water, my friend.",authorFa:"بروس لی",authorEn:"Bruce Lee",categoryFa:"انعطاف و کمال رزمی",categoryEn:"Fluid Mastery",theme:"mindfulness"},{id:"q_109",textFa:"هر روز فرصتی است تا گذشته را پشت سر بگذاری و آگاهانه از نو آغاز کنی.",textEn:"Each day is a fresh opportunity to leave the past behind and begin consciously anew.",authorFa:"آلن واتس",authorEn:"Alan Watts",categoryFa:"حضور در حال",categoryEn:"Zen & Timeless Now",theme:"mindfulness"},{id:"q_110",textFa:"به آنچه پشت سر شماست و آنچه پیش روی شماست فکر نکنید؛ آنچه درون شماست بی‌نهایت فراتر است.",textEn:"What lies behind us and what lies before us are tiny matters compared to what lies within us.",authorFa:"رالف والدو امرسون",authorEn:"Ralph Waldo Emerson",categoryFa:"اتکاء به نفس",categoryEn:"Self-Reliance",theme:"integrity"},{id:"q_111",textFa:"بهای هر چیز، مقدار حیاتی است که از زندگی‌ات در ازای آن می‌پردازی.",textEn:"The price of anything is the amount of life you exchange for it.",authorFa:"هنری دیوید ثورو",authorEn:"Henry David Thoreau",categoryFa:"سادگی و ارزش عمر",categoryEn:"Simplicity & Vitality",theme:"wealth"},{id:"q_112",textFa:"سه چیز برای شادکامی حقیقی در زندگی ضروری است: کاری برای انجام دادن، چیزی برای عشق ورزیدن و امیدی برای آینده.",textEn:"Three grand essentials to happiness in this life are something to do, something to love, and something to hope for.",authorFa:"جوزف ادیسون",authorEn:"Joseph Addison",categoryFa:"اصول شادکامی",categoryEn:"Essentials of Happiness",theme:"wisdom"},{id:"q_113",textFa:"آرامش واقعی زمانی آغاز می‌شود که نیازی به اثبات خودت به هیچ‌کس احساس نکنی.",textEn:"True inner peace begins the moment you choose not to allow another person or event to control your emotions.",authorFa:"پما چودرون",authorEn:"Pema Chodron",categoryFa:"صلح درون و رهایی",categoryEn:"Emotional Sovereignty",theme:"mindfulness"},{id:"q_114",textFa:"زندگی آزمون شجاعت است؛ یا یک ماجراجویی جسورانه است، یا هیچ چیز نیست.",textEn:"Life is either a daring adventure or nothing at all.",authorFa:"هلن کلر",authorEn:"Helen Keller",categoryFa:"جسارت و اشتیاق",categoryEn:"Daring Adventure",theme:"integrity"},{id:"q_115",textFa:"کلامی که با عشق و راستی بر زبان آید، قدرتمندتر از هزار شمشیر بران است.",textEn:"A word uttered with truth and love carries more power than a thousand sharpened swords.",authorFa:"خرد باستان شرق",authorEn:"Eastern Wisdom",categoryFa:"کلام نیک و اصالت",categoryEn:"Truthful Speech",theme:"integrity"},{id:"q_116",textFa:"بزرگ‌ترین افتخار ما در این نیست که هرگز سقوط نکنیم، بلکه در این است که بعد از هر سقوط دوباره برمی‌خیزیم.",textEn:"Our greatest glory is not in never falling, but in rising every time we fall.",authorFa:"کنفوسیوس",authorEn:"Confucius",categoryFa:"برخاستن و تاب‌آوری",categoryEn:"Rising after Failure",theme:"integrity"},{id:"q_117",textFa:"سرمایه‌گذاری روی ذهن، بالاترین سود را پرداخت می‌کند.",textEn:"An investment in knowledge pays the best interest.",authorFa:"بنجامین فرانکلین",authorEn:"Benjamin Franklin",categoryFa:"سرمایه دانایی",categoryEn:"Knowledge Compounding",theme:"wealth"},{id:"q_118",textFa:"اگر می‌خواهی جهان را دگرگون کنی، تخت‌خوابت را اول صبح مرتب کن؛ کارهای کوچک آغازگر تغییرات بزرگند.",textEn:"If you want to change the world, start off by making your bed. Discipline in small things builds champions.",authorFa:"ویلیام مک‌ریون",authorEn:"William H. McRaven",categoryFa:"انضباط فردی و شروع روز",categoryEn:"Micro Discipline",theme:"integrity"},{id:"q_119",textFa:"عشق به سرنوشت (Amor Fati)؛ نه تنها آنچه پیش می‌آید را تحمل کن، بلکه آن را صمیمانه دوست بدار.",textEn:"Amor Fati: Love your fate, which is in fact your life. Embrace whatever happens as necessary and transformative.",authorFa:"فریدریش نیچه",authorEn:"Friedrich Nietzsche",categoryFa:"عشق به تقدیر و سرنوشت",categoryEn:"Amor Fati & Stoic Joy",theme:"wisdom"},{id:"q_120",textFa:"در سکوت ذهن، تمام رازهای کائنات نجوا می‌شوند.",textEn:"In the stillness of the mind, the secrets of the cosmos are gently whispered.",authorFa:"خرد هرمسی",authorEn:"Hermetic Philosophy",categoryFa:"سکوت و شهود",categoryEn:"Intuition & Stillness",theme:"mindfulness"}];export{e as M};
